const item = $input.first().json;
let action = '';
let chatId = '';
let fromId = '';
let fromName = '';

if (item.callback_query) {
  action = item.callback_query.data || '';
  chatId = item.callback_query.message.chat.id;
  if (item.callback_query.from) {
    fromId = item.callback_query.from.id || '';
    fromName = (item.callback_query.from.first_name || '') + (item.callback_query.from.last_name ? ' ' + item.callback_query.from.last_name : '');
    if (!fromName) { fromName = item.callback_query.from.username || String(fromId); }
  }
} else if (item.message) {
  action = item.message.text || '';
  chatId = item.message.chat.id;
  if (item.message.from) {
    fromId = item.message.from.id || '';
    fromName = (item.message.from.first_name || '') + (item.message.from.last_name ? ' ' + item.message.from.last_name : '');
    if (!fromName) { fromName = item.message.from.username || String(fromId); }
  }
}

let category = '';
let route = 'categories';

if (action.startsWith('cat_')) {
  route = 'products';
  category = action.substring(4);
}

return [{ json: { action, chatId, category, route, fromId, fromName } }];

const ni = $('Normalize Input').first().json;
const action = (ni.action || '').toString();
const chatId = ni.chatId;
const telegram_id = String(chatId);

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && r.telegram_id !== undefined && String(r.telegram_id) !== '');
const sess = rows.find(r => String(r.telegram_id) === telegram_id);
let pantalla = '';
let carrito = '[]';
let datos = '{}';
if (sess) {
  pantalla = (sess.pantalla_actual || '').toString();
  carrito = (sess.carrito_temporal && String(sess.carrito_temporal).trim() !== '') ? String(sess.carrito_temporal) : '[]';
  datos = (sess.datos_checkout && String(sess.datos_checkout).trim() !== '') ? String(sess.datos_checkout) : '{}';
}

let route = 'categories';
let category = '';
let id_producto = '';
let cantidad = 0;
let subview = '';
let id_pedido_target = '';
let checkout_field = '';
let checkout_value = '';
let checkout_next = '';
let checkout_mode = '';
const isCheckout = pantalla.indexOf('checkout:') === 0;

const trimmed = action.trim();
const lower = trimmed.toLowerCase();
const greetings = ['hola','holi','buenas','buenos dias','buenos días','buenas tardes','buenas noches','/start','start','inicio','empezar','menu','menú'];
const isProductId = /^P\d+$/i.test(trimmed);
const isNumber = /^\d+$/.test(trimmed);
let search_term = '';

const REPORTS_GROUP = '-1004484176309';
if (telegram_id === REPORTS_GROUP) {
  if (action === 'rep_menu') { route = 'report_menu'; }
  else if (action === 'rep_consultar') { route = 'report_ask'; }
  else if (action === 'rep_estados') { route = 'report_estados'; }
  else if (action === 'rep_resumen') { route = 'report_resumen'; }
  else if (action === 'rep_pendientes') { route = 'report_pendientes'; }
  else if (action === 'rep_entregados') { route = 'report_entregados'; }
  else if (pantalla === 'report:search' && trimmed !== '' && action.indexOf('rep_') !== 0) { route = 'report_search'; search_term = trimmed; }
  else { route = 'report_menu'; }
  return [{ json: { action, chatId, telegram_id, route, category, id_producto, cantidad, subview, id_pedido_target, checkout_field, checkout_value, checkout_next, search_term, datos_checkout: datos, fromId: ni.fromId || '', fromName: ni.fromName || '', pantalla_actual: pantalla, carrito_temporal: carrito } }];
}

if (action.startsWith('cat_')) {
  route = 'products'; category = action.substring(4);
} else if (action.startsWith('add_')) {
  route = 'ask_quantity'; id_producto = action.substring(4);
} else if (action.startsWith('qty_')) {
  const parts = action.split('_'); id_producto = parts[1] || ''; cantidad = parseInt(parts[2] || '0', 10); route = 'add_to_cart';
} else if (action === 'cart_show') {
  route = 'view_cart'; subview = 'show';
} else if (action === 'cart_confirm') {
  route = 'view_cart'; subview = 'confirm';
} else if (action === 'order_confirm') {
  route = 'checkout_ask'; checkout_next = 'nombre'; checkout_mode = 'seq';
} else if (action === 'order_final') {
  route = 'process_order';
} else if (action === 'edit_info') {
  route = 'checkout_edit_menu';
} else if (action === 'review_show') {
  route = 'checkout_review';
} else if (action === 'edit_nombre') {
  route = 'checkout_ask'; checkout_next = 'nombre'; checkout_mode = 'edit';
} else if (action === 'edit_telefono') {
  route = 'checkout_ask'; checkout_next = 'telefono'; checkout_mode = 'edit';
} else if (action === 'edit_direccion') {
  route = 'checkout_ask'; checkout_next = 'direccion'; checkout_mode = 'edit';
} else if (action === 'edit_metodo') {
  route = 'checkout_pay'; checkout_mode = 'edit';
} else if (action.indexOf('pay_') === 0) {
  checkout_field = 'metodo_pago'; checkout_value = action.substring(4); route = 'checkout_review';
} else if (action.startsWith('adv_')) {
  route = 'advance_state'; id_pedido_target = action.substring(4);
} else if (action === 'ver_puntos') {
  route = 'view_points';
} else if (action === 'back_categories') {
  route = 'categories';
} else if (action === 'cancel_order') {
  route = 'cancel';
} else if (isCheckout) {
  const parts = pantalla.split(':');
  let field, mode;
  if (parts[1] === 'editf') { field = parts[2] || ''; mode = 'edit'; }
  else if (parts[1] === 'edit') { field = 'edit'; mode = 'edit'; }
  else { field = parts[1] || ''; mode = 'seq'; }

  if (field === 'edit') {
    const map = { '1': 'nombre', '2': 'telefono', '3': 'direccion', '4': 'metodo' };
    const sel = map[trimmed];
    if (sel === 'metodo') { route = 'checkout_pay'; checkout_mode = 'edit'; }
    else if (sel) { route = 'checkout_ask'; checkout_next = sel; checkout_mode = 'edit'; }
    else { route = 'checkout_edit_menu'; }
  } else if (field === 'nombre' || field === 'telefono' || field === 'direccion') {
    checkout_field = field; checkout_value = trimmed; checkout_mode = mode;
    if (field === 'telefono' && !/^\d{10}$/.test(trimmed)) {
      route = 'checkout_phone_error';
    } else if (mode === 'edit') {
      route = 'checkout_review';
    } else if (field === 'nombre') {
      route = 'checkout_ask'; checkout_next = 'telefono';
    } else if (field === 'telefono') {
      route = 'checkout_ask'; checkout_next = 'direccion';
    } else {
      route = 'checkout_pay';
    }
  } else {
    route = 'checkout_review';
  }
} else if (isProductId) {
  route = 'ask_quantity'; id_producto = trimmed.toUpperCase();
} else if (isNumber && pantalla.indexOf('cantidad:') === 0) {
  route = 'add_to_cart'; id_producto = pantalla.split(':')[1] || ''; cantidad = parseInt(trimmed, 10);
} else if (greetings.indexOf(lower) !== -1) {
  route = 'welcome';
} else {
  route = 'invalid';
}

return [{ json: { action, chatId, telegram_id, route, category, id_producto, cantidad, subview, id_pedido_target, checkout_field, checkout_value, checkout_next, checkout_mode, search_term, datos_checkout: datos, fromId: ni.fromId || '', fromName: ni.fromName || '', pantalla_actual: pantalla, carrito_temporal: carrito } }];

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && Object.keys(r).length > 0 && r.id_producto !== undefined && r.id_producto !== '');

const chatId = $('Normalize Input').first().json.chatId;
const category = $('Normalize Input').first().json.category;

let text;
if (rows.length === 0) {
  text = 'No hay productos disponibles en la categoría *' + category + '*.';
} else {
  const lines = rows.map(function (r) {
    const disponible = Number(r.stock) > 0
      ? '✅ Disponible (' + r.stock + ')'
      : '❌ Agotado';
    return '🆔 ' + r.id_producto + ' — *' + r.nombre + '*\n' +
      (r.descripcion ? r.descripcion + '\n' : '') +
      '💲 ' + r.precio + '  |  ' + disponible;
  });
  text = '🍽️ *' + category + '*\n\n' + lines.join('\n\n') + '\n\n✍️ Para agregar, escribe el ID del producto (ej. ' + rows[0].id_producto + ').';
}

return [{ json: { chatId: chatId, text: text } }];

const dr = $('Determine Route').first().json;
const prodRows = $('Lookup Product').all().map(i => i.json).filter(r => r && r.id_producto !== undefined && r.id_producto !== '');
const prod = prodRows.find(r => String(r.id_producto).toUpperCase() === String(dr.id_producto).toUpperCase());
let cart = [];
try { cart = JSON.parse(dr.carrito_temporal || '[]'); } catch (e) { cart = []; }
if (!Array.isArray(cart)) { cart = []; }
const cantidad = Number(dr.cantidad) || 0;
let note = '';
if (!prod) {
  note = '⚠️ No encontré el producto ' + dr.id_producto + '.\n\n';
} else if (cantidad <= 0) {
  note = '⚠️ Cantidad inválida.\n\n';
} else {
  const existing = cart.find(c => String(c.id_producto).toUpperCase() === String(prod.id_producto).toUpperCase());
  if (existing) {
    existing.cantidad = Number(existing.cantidad) + cantidad;
  } else {
    cart.push({ id_producto: prod.id_producto, nombre: prod.nombre, precio: Number(prod.precio), cantidad: cantidad });
  }
}
let total = 0;
const lines = cart.map(function (c) {
  const sub = Number(c.precio) * Number(c.cantidad);
  total += sub;
  return '• ' + c.cantidad + ' × ' + c.nombre + ' — $' + sub;
});
const body = lines.length ? lines.join('\n') : 'Tu carrito está vacío.';
const text = note + '🛒 *Tu carrito*\n\n' + body + '\n\n*Total: $' + total + '*';
return [{ json: { telegram_id: dr.telegram_id, chatId: dr.chatId, carrito_temporal: JSON.stringify(cart), ultimo_cambio: new Date().toISOString(), pantalla_actual: 'carrito', text: text, total: total } }];

const dr = $('Determine Route').first().json;
let cart = [];
try { cart = JSON.parse(dr.carrito_temporal || '[]'); } catch (e) { cart = []; }
if (!Array.isArray(cart)) { cart = []; }
let total = 0;
const lines = cart.map(function (c) {
  const sub = Number(c.precio) * Number(c.cantidad);
  total += sub;
  return '• ' + c.cantidad + ' × ' + c.nombre + ' — $' + sub;
});
const body = lines.length ? lines.join('\n') : 'Tu carrito está vacío.';
const header = dr.subview === 'confirm' ? '🧾 *Confirmación del pedido*' : '🛒 *Tu carrito*';
const footer = dr.subview === 'confirm' ? '\n\n¿Confirmar tu pedido?' : '';
const text = header + '\n\n' + body + '\n\n*Total: $' + total + '*' + footer;
return [{ json: { chatId: dr.chatId, text: text, subview: dr.subview || 'show' } }];

const dr = $('Determine Route').first().json;
const chatId = dr.chatId;
const telegram_id = dr.telegram_id;
let cart = [];
try { cart = JSON.parse(dr.carrito_temporal || '[]'); } catch (e) { cart = []; }
if (!Array.isArray(cart)) { cart = []; }
const menu = $input.all().map(i => i.json).filter(r => r && r.id_producto !== undefined && String(r.id_producto) !== '');

if (cart.length === 0) {
  return [{ json: { ok: false, chatId: chatId, telegram_id: telegram_id, message: '🛒 Tu carrito está vacío. Agrega productos antes de confirmar.' } }];
}

const problems = [];
const items = [];
let total = 0;
for (const c of cart) {
  const m = menu.find(r => String(r.id_producto).toUpperCase() === String(c.id_producto).toUpperCase());
  const cantidad = Number(c.cantidad) || 0;
  if (!m) { problems.push('• ' + c.nombre + ' (' + c.id_producto + ') ya no está disponible en el menú'); continue; }
  const stock = Number(m.stock) || 0;
  if (cantidad > stock) { problems.push('• ' + m.nombre + ': pediste ' + cantidad + ' pero solo hay ' + stock + ' disponibles'); }
  const precio = Number(c.precio);
  total += precio * cantidad;
  items.push({ id_producto: m.id_producto, nombre: m.nombre, precio: precio, cantidad: cantidad, stock_actual: stock });
}

if (problems.length) {
  return [{ json: { ok: false, chatId: chatId, telegram_id: telegram_id, message: '⚠️ No pude confirmar el pedido por falta de stock:\n\n' + problems.join('\n') + '\n\nAjusta tu carrito e inténtalo de nuevo.' } }];
}

return [{ json: { ok: true, chatId: chatId, telegram_id: telegram_id, items: items, total: total, detalles: JSON.stringify(cart) } }];

const vs = $('Validate Stock').first().json;
const dr = $('Determine Route').first().json;
let datos = {}; try { datos = JSON.parse(dr.datos_checkout || '{}'); } catch (e) { datos = {}; }
const nombre_cliente = datos.nombre || '';
const telefono = datos.telefono || '';
const direccion = datos.direccion || '';
const metodo_pago = datos.metodo_pago || dr.checkout_value || '';
const pedidos = $('Read PEDIDOS').all().map(i => i.json).filter(r => r && r.id_pedido !== undefined && String(r.id_pedido) !== '');

const datePrefix = $now.toFormat('yyyyMMdd');
const prefix = 'PED-' + datePrefix + '-';
let maxSeq = 0;
for (const p of pedidos) {
  const idp = String(p.id_pedido || '');
  if (idp.indexOf(prefix) === 0) {
    const seq = parseInt(idp.substring(prefix.length), 10);
    if (!isNaN(seq) && seq > maxSeq) { maxSeq = seq; }
  }
}
const nextSeq = String(maxSeq + 1).padStart(4, '0');
const id_pedido = prefix + nextSeq;

const items = vs.items || [];
const stock_updates = items.map(function (it) {
  return { id_producto: it.id_producto, stock: Number(it.stock_actual) - Number(it.cantidad) };
});
const lines = items.map(function (it) { return it.cantidad + ' × ' + it.nombre; });
const total = vs.total;
const fecha = $now.toFormat('yyyy-MM-dd');
const hora = $now.toFormat('HH:mm:ss');

const kitchen_text = '🍳 NUEVO PEDIDO\nPedido: ' + id_pedido + '\n\n' + lines.join('\n') + '\n\nTotal: $' + total + '\nEstado: Recibido';
const user_text = '✅ Pedido recibido\n\nNúmero de pedido: ' + id_pedido + '\n\n' + lines.join('\n') + '\n\nTotal: $' + total + '\n\nEstado: Recibido';

return [{ json: { id_pedido: id_pedido, id_usuario: vs.telegram_id, telegram_id: vs.telegram_id, chatId: vs.chatId, detalles_pedido: vs.detalles, total_pago: total, estado: 'Recibido', fecha: fecha, hora: hora, nombre_cliente: nombre_cliente, telefono: telefono, direccion: direccion, metodo_pago: metodo_pago, stock_updates: stock_updates, kitchen_text: kitchen_text, user_text: user_text } }];

const bo = $('Build Order').first().json;
const ups = bo.stock_updates || [];
return ups.map(function (u) { return { json: { id_producto: u.id_producto, stock: u.stock } }; });

const dr = $('Determine Route').first().json;
const id_pedido = dr.id_pedido_target;
const changedBy = dr.fromName || String(dr.fromId || '') || 'desconocido';
const chatIdStaff = dr.chatId;
const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido !== undefined && String(r.id_pedido) !== '');
const pedido = rows.find(r => String(r.id_pedido) === String(id_pedido));

const flow = ['Recibido', 'En preparación', 'En camino', 'Entregado'];
const messages = {
  'Recibido': '✅ Hemos recibido tu pedido. En breve comenzaremos a prepararlo.',
  'En preparación': '👨‍🍳 Tu pedido ya está en preparación. ¡Estamos trabajando en él!',
  'En camino': '🛵 ¡Tu pedido está en camino! Pronto estará llegando a la dirección indicada.',
  'Entregado': '🎉 ¡Tu pedido ha sido entregado! Gracias por comprar con nosotros.'
};

if (!pedido) {
  return [{ json: { can_advance: false, staff_chat: chatIdStaff, staff_message: '⚠️ No encontré el pedido ' + id_pedido + '.' } }];
}

const estadoActual = String(pedido.estado || 'Recibido');
const idx = flow.indexOf(estadoActual);

if (estadoActual === 'Entregado' || idx === flow.length - 1) {
  return [{ json: { can_advance: false, staff_chat: chatIdStaff, staff_message: '🔒 El pedido ' + id_pedido + ' ya está *Entregado*. No puede avanzar más.' } }];
}
if (idx === -1) {
  return [{ json: { can_advance: false, staff_chat: chatIdStaff, staff_message: '⚠️ Estado desconocido para el pedido ' + id_pedido + '.' } }];
}

const nuevoEstado = flow[idx + 1];
const cliente_chat = pedido.id_usuario;
const cliente_message = messages[nuevoEstado];
const isFinal = nuevoEstado === 'Entregado';
const staff_message = '✅ Pedido ' + id_pedido + ': *' + estadoActual + '* → *' + nuevoEstado + '*.';

return [{ json: {
  can_advance: true,
  id_pedido: id_pedido,
  estado_anterior: estadoActual,
  estado_nuevo: nuevoEstado,
  is_final: isFinal,
  changed_by: changedBy,
  staff_chat: chatIdStaff,
  staff_message: staff_message,
  cliente_chat: cliente_chat,
  cliente_message: cliente_message,
  fecha: $now.toFormat('yyyy-MM-dd'),
  hora: $now.toFormat('HH:mm:ss'),
  p_id_usuario: pedido.id_usuario,
  p_nombre: pedido.nombre_cliente || '',
  p_telefono: pedido.telefono || '',
  p_direccion: pedido.direccion || '',
  p_metodo: pedido.metodo_pago || '',
  p_detalles: pedido.detalles_pedido || '[]',
  p_total: pedido.total_pago,
  p_fecha_creacion: pedido.fecha || '',
  p_hora_creacion: pedido.hora || '',
  cambio_iso: $now.toISO()
} }];

const s = $('Compute Next State').first().json;
return [{ json: {
  id_pedido: s.id_pedido,
  estado_anterior: s.estado_anterior,
  estado_nuevo: s.estado_nuevo,
  fecha: s.fecha,
  hora: s.hora,
  cambiado_por: s.changed_by,
  notificacion: 'enviada'
} }];

const s = $('Compute Next State').first().json;
return [{ json: {
  id_pedido: s.id_pedido,
  estado_anterior: s.estado_anterior,
  estado_nuevo: s.estado_nuevo,
  fecha: s.fecha,
  hora: s.hora,
  cambiado_por: s.changed_by,
  notificacion: 'error al enviar'
} }];

const s = $('Compute Next State').first().json;
const yaRegistrado = $input.all().map(i => i.json).filter(r => r && r.id_pedido !== undefined && String(r.id_pedido) === String(s.id_pedido));

if (yaRegistrado.length > 0) {
  return [{ json: { already: true, staff_chat: s.staff_chat, resumen: '' } }];
}

let productos = [];
try { productos = JSON.parse(s.p_detalles || '[]'); } catch (e) { productos = []; }
if (!Array.isArray(productos)) { productos = []; }
const lineas = productos.map(function (p) { return '• ' + p.cantidad + ' × ' + p.nombre; });
const lista = lineas.length ? lineas.join('\n') : '(sin detalle)';

const creado = (s.p_fecha_creacion && s.p_hora_creacion) ? (s.p_fecha_creacion + 'T' + s.p_hora_creacion) : '';
const entregadoDT = s.fecha + 'T' + s.hora;
let tiempoTexto = 'N/D';
let dCreado = creado ? new Date(creado) : null;
let dEntregado = new Date(entregadoDT);
if (dCreado && !isNaN(dCreado.getTime()) && !isNaN(dEntregado.getTime())) {
  let diffMs = dEntregado.getTime() - dCreado.getTime();
  if (diffMs < 0) { diffMs = 0; }
  const totalMin = Math.floor(diffMs / 60000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  tiempoTexto = (h > 0 ? h + 'h ' : '') + m + 'min';
}

const creado_str = creado ? (s.p_fecha_creacion + ' ' + s.p_hora_creacion) : 'N/D';
const entregado_str = s.fecha + ' ' + s.hora;

const resumen = 'PEDIDO #' + s.id_pedido + '\n\n' +
  '👤 Cliente: ' + (s.p_nombre || 'N/D') + '\n' +
  '📞 Teléfono: ' + (s.p_telefono || 'N/D') + '\n' +
  '📍 Dirección: ' + (s.p_direccion || 'N/D') + '\n\n' +
  '🛒 Productos:\n' + lista + '\n\n' +
  '💰 Total: $' + s.p_total + '\n' +
  '💳 Método de pago: ' + (s.p_metodo || 'N/D') + '\n\n' +
  '🕐 Creado: ' + creado_str + '\n' +
  '🛵 Entregado: ' + entregado_str + '\n' +
  '⏱️ Tiempo total: ' + tiempoTexto + '\n\n' +
  '✅ Estado: ENTREGADO';

return [{ json: {
  already: false,
  id_pedido: s.id_pedido,
  nombre_cliente: s.p_nombre || '',
  telefono: s.p_telefono || '',
  direccion: s.p_direccion || '',
  productos: s.p_detalles || '[]',
  total_pago: s.p_total,
  metodo_pago: s.p_metodo || '',
  fecha_creacion: creado_str,
  fecha_entrega: entregado_str,
  estado_final: 'Entregado',
  tiempo_total_pedido: tiempoTexto,
  staff_chat: s.staff_chat,
  resumen: resumen
} }];

const dr = $('Determine Route').first().json;
let datos = {}; try { datos = JSON.parse(dr.datos_checkout || '{}'); } catch (e) { datos = {}; }
if (!datos || typeof datos !== 'object') { datos = {}; }

if (dr.checkout_field) { datos[dr.checkout_field] = dr.checkout_value; }

const next = dr.checkout_next || 'nombre';
const isEdit = dr.checkout_mode === 'edit';
const labels = {
  'nombre': '👤 Escribe tu *nombre completo*:',
  'telefono': '📞 Escribe tu *teléfono* (exactamente *10 dígitos*, solo números):',
  'direccion': '📍 Escribe tu *dirección de entrega*:'
};
let intro = '';
if (next === 'nombre' && !isEdit) { intro = '🧾 *Para confirmar tu pedido, necesito algunos datos.*\n\n'; }
if (isEdit) { intro = '✏️ *Editar información*\n\n'; }
const text = intro + (labels[next] || 'Escribe el dato:');
const pantalla = isEdit ? ('checkout:editf:' + next) : ('checkout:' + next);

return [{ json: {
  telegram_id: dr.telegram_id,
  chatId: dr.chatId,
  datos_checkout: JSON.stringify(datos),
  pantalla_actual: pantalla,
  text: text,
  ultimo_cambio: new Date().toISOString()
} }];

const term = String($('Determine Route').first().json.search_term || '').trim();
const chatId = $('Determine Route').first().json.chatId;
const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido !== undefined && String(r.id_pedido) !== '');
const t = term.toLowerCase();

const matches = rows.filter(function (r) {
  const id = String(r.id_pedido || '').toLowerCase();
  const nombre = String(r.nombre_cliente || '').toLowerCase();
  const tel = String(r.telefono || '').toLowerCase();
  const estado = String(r.estado || '').toLowerCase();
  const fecha = String(r.fecha || '').toLowerCase();
  return id === t || nombre.indexOf(t) !== -1 || tel.indexOf(t) !== -1 || estado === t || fecha === t;
});

let text;
if (matches.length === 0) {
  text = '🔍 No encontré pedidos que coincidan con: *' + term + '*';
} else {
  const blocks = matches.slice(0, 15).map(function (r) {
    return '🧾 *' + r.id_pedido + '*\n' +
      '👤 ' + (r.nombre_cliente || 'N/D') + '\n' +
      '📞 ' + (r.telefono || 'N/D') + '\n' +
      '📍 ' + (r.direccion || 'N/D') + '\n' +
      '📦 Estado: ' + (r.estado || 'N/D') + '\n' +
      '💰 Total: $' + (r.total_pago != null ? r.total_pago : 'N/D') + '\n' +
      '💳 ' + (r.metodo_pago || 'N/D') + '\n' +
      '🕐 ' + (r.fecha || 'N/D') + ' ' + (r.hora || '');
  });
  let header = '🔍 *Resultados para:* ' + term + ' (' + matches.length + ')\n\n';
  if (matches.length > 15) { header += '_Mostrando los primeros 15._\n\n'; }
  text = header + blocks.join('\n\n');
}
return [{ json: { chatId: chatId, text: text } }];

const chatId = $('Determine Route').first().json.chatId;
