const chatId = $('Determine Route').first().json.chatId;
const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido !== undefined && String(r.id_pedido) !== '');
const pendientes = rows.filter(function (r) { return String(r.estado || '').trim() !== 'Entregado'; });
const now = new Date();

function transcurrido(fecha, hora) {
  if (!fecha) { return 'N/D'; }
  const d = new Date(String(fecha) + 'T' + (hora ? String(hora) : '00:00:00'));
  if (isNaN(d.getTime())) { return 'N/D'; }
  let diff = now.getTime() - d.getTime();
  if (diff < 0) { diff = 0; }
  const totalMin = Math.floor(diff / 60000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  return (h > 0 ? h + 'h ' : '') + m + 'min';
}

let text;
if (pendientes.length === 0) {
  text = '⏳ *Pedidos pendientes*\n\nNo hay pedidos pendientes. 🎉';
} else {
  const blocks = pendientes.slice(0, 20).map(function (r) {
    return '🧾 *' + r.id_pedido + '*\n' +
      '👤 ' + (r.nombre_cliente || 'N/D') + '\n' +
      '📦 ' + (r.estado || 'N/D') + '\n' +
      '💰 $' + (r.total_pago != null ? r.total_pago : 'N/D') + '\n' +
      '🕐 ' + (r.fecha || 'N/D') + ' ' + (r.hora || '') + '\n' +
      '⏱️ Hace ' + transcurrido(r.fecha, r.hora);
  });
  let header = '⏳ *Pedidos pendientes* (' + pendientes.length + ')\n\n';
  if (pendientes.length > 20) { header += '_Mostrando los primeros 20._\n\n'; }
  text = header + blocks.join('\n\n');
}
return [{ json: { chatId: chatId, text: text } }];

